#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string S;
    if (!(cin >> S)) return 0;

    // 6 siklus cantik berperiode 3 yang mungkin:
    vector<string> patterns = {
        "OSN", "ONS", "SNO", "SON", "NOS", "NSO"
    };

    int max_len = -1;

    for (const string &pat : patterns) {
        int pat_idx = 0;
        int matched = 0;
        for (char c : S) {
            if (c == pat[pat_idx % 3]) {
                matched++;
                pat_idx++;
            }
        }
        if (matched >= 3) {
            max_len = max(max_len, matched);
        }
    }

    cout << max_len << "\n";
    return 0;
}

#include <iostream>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long B, C, D;
    if (!(cin >> B >> C >> D)) return 0;

    // Persamaan: C = q * k + D dengan k > D dan k <= B
    // Kasus 1: D == C
    // q * k = 0 -> q = 0, k bisa sembarang nilai > C dan <= B
    if (D == C) {
        if (B > C) {
            cout << (B - C) << "\n";
        } else {
            cout << 0 << "\n";
        }
        return 0;
    }

    // Kasus 2: D < C
    // k harus merupakan pembagi dari (C - D) dengan D < k <= B
    long long diff = C - D;
    long long count = 0;

    for (long long i = 1; i * i <= diff; ++i) {
        if (diff % i == 0) {
            long long k1 = i;
            long long k2 = diff / i;

            if (k1 > D && k1 <= B) count++;
            if (k2 != k1 && k2 > D && k2 <= B) count++;
        }
    }

    cout << count << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    long long M;
    if (!(cin >> N >> M)) return 0;

    vector<long long> A(N);
    long long max_h = 0;
    long long total_wood = 0;

    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        max_h = max(max_h, A[i]);
        total_wood += A[i];
    }

    if (total_wood < M) {
        cout << -1 << "\n";
        return 0;
    }

    long long low = 0, high = max_h;
    long long ans = 0;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long wood = 0;
        for (int i = 0; i < N; ++i) {
            if (A[i] > mid) {
                wood += (A[i] - mid);
            }
        }
        if (wood >= M) {
            ans = mid;
            low = mid + 1; // Coba cari ketinggian yang lebih tinggi
        } else {
            high = mid - 1;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long B;
    string Y;
    if (!(cin >> B >> Y)) return 0;

    int n = Y.length();
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < n; ++i) {
        if (dp[i] == 0) continue;

        // Coba bentuk digit dari substring Y[i..j-1]
        long long current_val = 0;
        for (int j = i + 1; j <= n; ++j) {
            current_val = current_val * 10 + (Y[j - 1] - '0');
            if (current_val >= B) break; // Melebihi basis B

            dp[j] = (dp[j] + dp[i]) % MOD;

            // Jika digit bernilai 0, tidak boleh ada digit multi-karakter dengan awalan 0
            if (current_val == 0) break;
        }
    }

    cout << dp[n] << "\n";
    return 0;
}

#include <iostream>
