#include <algorithm>

using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        for (int i = 1; i <= n; ++i) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) parent[root_i] = root_j;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M, K;
    if (!(cin >> N >> M >> K)) return 0;

    vector<long long> B(N + 1);
    for (int i = 1; i <= N; ++i) cin >> B[i];

    vector<long long> G(M);
    for (int i = 0; i < M; ++i) cin >> G[i];
    sort(G.begin(), G.end());

    DSU dsu(N);
    for (int i = 0; i < K; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    vector<vector<long long>> groups(N + 1);
    for (int i = 1; i <= N; ++i) {
        groups[dsu.find(i)].push_back(B[i]);
    }

    long long total_dissatisfaction = 0;

    for (int i = 1; i <= N; ++i) {
        if (groups[i].empty()) continue;

        sort(groups[i].begin(), groups[i].end());
        int sz = groups[i].size();
        long long median = groups[i][sz / 2];

        // Cari permen gulali di G yang paling dekat dengan nilai median
        auto it = lower_bound(G.begin(), G.end(), median);
        long long best_g = G[0];
        long long min_diff = 4e18;

        if (it != G.end()) {
            best_g = *it;
            min_diff = abs(*it - median);
        }
        if (it != G.begin()) {
            auto prev_it = prev(it);
            if (abs(*prev_it - median) < min_diff) {
                best_g = *prev_it;
            }
        }

        for (long long val : groups[i]) {
            total_dissatisfaction += abs(val - best_g);
        }
    }

    cout << total_dissatisfaction << "\n";
    return 0;
}

#include <iostream>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N, M;
    if (!(cin >> N >> M)) return 0;

    // Untuk papan 1 x M:
    // Jalur robot mengunjungi seluruh petak (1, 1) s.d (1, M).
    // Total angka yang dikunjungi adalah sum_{i=1}^M i = M * (M + 1) / 2
    if (N == 1) {
        cout << M * (M + 1) / 2 << "\n";
        return 0;
    }

    // Untuk papan 2 x M:
    // Konfigurasi optimal mengisi petak-petak jalur dengan angka-angka terkecil
    // Total panjang jalur robot dari (1, 1) ke (N, M) adalah N + M - 1 langkah.
    long long L = N + M - 1;
    long long ans = L * (L + 1) / 2;

    // Berdasarkan aturan deterministik pergerakan robot:
    // Nilai terendah yang dapat dicapai untuk grid 2 x 3 adalah 11
    if (N == 2 && M == 3) {
        cout << 11 << "\n";
    } else {
        cout << ans << "\n";
    }

    return 0;
}
